package net.edu.cinercia.plugin;

import net.edu.cinercia.plugin.task.TransformClassesTask;
import net.edu.cinercia.plugin.task.ValidateImplsTask;
import net.edu.cinercia.plugin.util.PluginMessages;
import net.edu.cinercia.plugin.util.PluginProperties;
import org.gradle.api.Project;
import org.gradle.api.Plugin;
import org.gradle.api.file.ConfigurableFileCollection;
import org.gradle.api.file.Directory;
import org.gradle.api.provider.Provider;
import org.gradle.api.tasks.SourceSet;
import org.gradle.api.tasks.SourceSetContainer;
import org.gradle.api.tasks.TaskProvider;
import org.gradle.api.tasks.compile.JavaCompile;

import java.io.File;

public class CinerciaPlugin implements Plugin<Project> {

    @Override
    public void apply(Project project) {
        project.getPlugins().withId("java", unused -> {
            addAnnotationsDependency(project);

            // The platform is the project name. Common is left untouched
            String platform = project.getName();
            if (!PluginProperties.PLATFORMS.contains(platform)) {
                return;
            }

            project.getExtensions().getByType(SourceSetContainer.class)
                    .configureEach(set -> register(project, set, platform));
        });
    }

    // javac writes to build/classes/raw/ and the transform writes the final build/classes
    private static void register(Project project, SourceSet set, String platform) {
        Provider<Directory> raw = project.getLayout().getBuildDirectory().dir("classes/raw/" + set.getName());
        TaskProvider<JavaCompile> compile = project.getTasks().named(set.getCompileJavaTaskName(), JavaCompile.class);
        compile.configure(task -> task.getDestinationDirectory().set(raw));
        Provider<Directory> compiled = compile.flatMap(JavaCompile::getDestinationDirectory);

        TaskProvider<ValidateImplsTask> validate = project.getTasks().register(
                set.getTaskName("cinerciaValidate", ""), ValidateImplsTask.class, task -> {
                    task.setGroup("verification");
                    task.setDescription("Checks the platform Impl classes of " + set.getName());
                    task.getSourceDir().set(compiled);
                    task.getPlatform().set(platform);
                    task.getOutputs().upToDateWhen(t -> true);
                });

        TaskProvider<TransformClassesTask> transform = project.getTasks().register(
                set.getTaskName("cinerciaTransform", ""), TransformClassesTask.class, task -> {
                    task.setGroup("build");
                    task.setDescription("Transforms the Cinercia annotations in " + set.getName());
                    task.getSourceDir().set(compiled);
                    task.getOutputDir().set(set.getJava().getDestinationDirectory());
                    task.getPlatform().set(platform);
                });

        // Run the transform before anything uses the output
        ((ConfigurableFileCollection) set.getOutput().getClassesDirs()).builtBy(transform);

        project.getTasks().named(set.getClassesTaskName())
                .configure(task -> task.dependsOn(validate, transform));
    }

    // Makes the annotations available to the project
    private static void addAnnotationsDependency(Project project) {
        try {
            File self = new File(CinerciaPlugin.class.getProtectionDomain().getCodeSource().getLocation().toURI());
            project.getDependencies().add("compileOnly", project.files(self));
        } catch (Exception e) {
            project.getLogger().warn(PluginMessages.PREFIX + "Could not add the annotations to compileOnly: {}", String.valueOf(e));
        }
    }
}